
select jsonb_build_object(
'columns', (select coalesce(jsonb_agg(to_jsonb(x) order by x.table_name,x.ordinal_position),'[]'::jsonb) from (select table_schema as schema,table_name,column_name,ordinal_position,data_type,udt_schema,udt_name,is_nullable,column_default,character_maximum_length,numeric_precision,numeric_scale,is_identity,identity_generation from information_schema.columns where table_schema in ('public','private')) x),
'constraints',(select coalesce(jsonb_agg(to_jsonb(x) order by x.table_name,x.name),'[]'::jsonb) from (select n.nspname as schema,c.relname as table_name,con.conname as name,con.contype as type,con.convalidated as validated,pg_get_constraintdef(con.oid,true) as definition from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')) x),
'indexes',(select coalesce(jsonb_agg(to_jsonb(x) order by x.tablename,x.indexname),'[]'::jsonb) from (select schemaname as schema,tablename,indexname,indexdef from pg_indexes where schemaname in ('public','private')) x),
'policies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.tablename,x.policyname),'[]'::jsonb) from (select schemaname as schema,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname in ('public','private')) x),
'functions',(select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.identity_arguments),'[]'::jsonb) from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as identity_arguments,pg_get_function_result(p.oid) as result_type,pg_get_userbyid(p.proowner) as owner,p.prosecdef as security_definer,p.proconfig as config,p.proacl::text as acl,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f') x),
'triggers',(select coalesce(jsonb_agg(to_jsonb(x) order by x.table_name,x.name),'[]'::jsonb) from (select n.nspname as schema,c.relname as table_name,t.tgname as name,pg_get_triggerdef(t.oid,true) as definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and not t.tgisinternal) x),
'grants',(select coalesce(jsonb_agg(to_jsonb(x) order by x.table_name,x.grantee,x.privilege_type),'[]'::jsonb) from (select table_schema as schema,grantee,table_name,privilege_type,is_grantable from information_schema.role_table_grants where table_schema in ('public','private')) x),
'column_grants',(select coalesce(jsonb_agg(to_jsonb(x) order by x.table_name,x.column_name,x.grantee,x.privilege_type),'[]'::jsonb) from (select table_schema as schema,grantee,table_name,column_name,privilege_type,is_grantable from information_schema.role_column_grants where table_schema in ('public','private')) x),
'types',(select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.enum_sort_order),'[]'::jsonb) from (select n.nspname as schema,t.typname as name,e.enumlabel as enum_label,e.enumsortorder as enum_sort_order from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname in ('public','private')) x),
'extensions',(select coalesce(jsonb_agg(to_jsonb(x) order by x.name),'[]'::jsonb) from (select e.extname as name,e.extversion as version,n.nspname as schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace) x)
) as snapshot;

